const IMG = {};
function loadAssets() {
  for (const k in ASSETS) {
    const im = new Image();
    im.src = ASSETS[k];
    IMG[k] = im;
  }
  // SPINE 烘焙特效精灵表
  for (const k in FX_SHEETS) {
    const im = new Image();
    im.src = FX_SHEETS[k];
    IMG['fx_' + k] = im;
  }
}
function imgReady(k) { return IMG[k] && IMG[k].complete && IMG[k].naturalWidth > 0; }

